                break;
            } else if (mid < pos) {
                constrainedIndices.add(mid);
                l = mid + 1;
            } else {
                constrainedIndices.add(mid);
                r = mid - 1;
            }
        }

        // Now, the constrained indices (excluding pos) must have values satisfying:
        // - If index < pos: value < x
        // - If index > pos: value > x

        // The number of such indices:
        int countLess = 0; // indices < pos that are constrained
        int countGreater = 0; // indices > pos that are constrained
        for (int idx : constrainedIndices) {
            if (idx < pos) countLess++;
            else countGreater++;
        }

        // Available values for positions with constraint "value < x":
        // Values 1, 2, ..., x-1. There are (x-1) such values.
        // We need to assign distinct values from these to the countLess positions.
        // Number of ways: P(x-1, countLess) = (x-1)! / (x-1-countLess)!

        // Available values for positions with constraint "value > x":
        // Values x+1, x+2, ..., n. There are (n-x) such values.
        // We need to assign distinct values from these to the countGreater positions.
        // Number of ways: P(n-x, countGreater) = (n-x)! / (n-x-countGreater)!

        // If countLess > x-1 or countGreater > n-x, then it's impossible.
        if (countLess > x - 1 || countGreater > n - x) {
            System.out.println(0);
            return;
        }

        long waysLess = fact[x - 1] * modInverse(fact[x - 1 - countLess], MOD) % MOD;
        long waysGreater = fact[n - x] * modInverse(fact[n - x - countGreater], MOD) % MOD;

        // The remaining positions (not pos, not in constrainedIndices) can have any of the remaining values.
        // Total positions: n
        // Fixed: pos (1 position)
        // Constrained: countLess + countGreater positions
        // Remaining: n - 1 - countLess - countGreater positions

        // Remaining values: total values n, minus x (used at pos), minus countLess (used in less-constrained),
        // minus countGreater (used in greater-constrained).
        // So remaining values = n - 1 - countLess - countGreater.
        // These can be arranged in (n - 1 - countLess - countGreater)! ways.

        int remaining = n - 1 - countLess - countGreater;
        long waysRemaining = fact[remaining];

        long result = waysLess * waysGreater % MOD * waysRemaining % MOD;
        System.out.println(result);
    }

    static long modInverse(long a, long mod) {
        return pow(a, mod - 2, mod);
    }

    static long pow(long base, long exp, long mod) {
        long result = 1;
        base %= mod;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = result * base % mod;
            }
            base = base * base % mod;
            exp >>= 1;
        }
        return result;
    }
}
