        int n = Integer.parseInt(st.nextToken());
        int x = Integer.parseInt(st.nextToken());
        int pos = Integer.parseInt(st.nextToken());

        // Precompute factorials
        long[] fact = new long[n + 1];
        fact[0] = 1;
        for (int i = 1; i <= n; i++) {
            fact[i] = fact[i - 1] * i % MOD;
        }

        // Simulate binary search to find the path
        // We need to determine for each step whether the search goes left or right
        // The binary search algorithm:
        // l = 0, r = n - 1
        // while l <= r:
        //   mid = (l + r) / 2
        //   if a[mid] == x: return true
        //   if a[mid] < x: l = mid + 1
        //   else: r = mid - 1
        // return false

        // For the algorithm to find x at position 'pos', we need:
        // 1. x must be at position 'pos'
        // 2. The binary search must reach 'pos' and compare a[pos] with x
        // 3. Before reaching 'pos', all comparisons must direct the search towards 'pos'

        // Let's simulate the binary search and track the interval [l, r]
        // At each step, mid is computed. If mid == pos, we're done (found x).
        // If mid < pos, we need a[mid] < x so that l becomes mid + 1
        // If mid > pos, we need a[mid] > x so that r becomes mid - 1

        // Count the number of positions that are "visited" by the binary search before reaching pos
        // and determine the constraints on those positions.

        int l = 0;
        int r = n - 1;
        int countLess = 0; // number of positions where we need a[i] < x
        int countGreater = 0; // number of positions where we need a[i] > x
        boolean found = false;

        while (l <= r) {
            int mid = (l + r) / 2;
            if (mid == pos) {
                found = true;
                break;
            } else if (mid < pos) {
                // We need a[mid] < x to move right
                countLess++;
                l = mid + 1;
            } else {
                // We need a[mid] > x to move left
                countGreater++;
                r = mid - 1;
            }
        }

        if (!found) {
            // The binary search never reaches pos
            System.out.println(0);
            return;
        }

        // Now, we have:
        // - pos is fixed to x
        // - countLess positions must have values < x
        // - countGreater positions must have values > x
        // - The remaining positions (n - 1 - countLess - countGreater) can have any value from the remaining pool

        // Total numbers available: 1 to n, excluding x
        // Numbers less than x: x - 1
        // Numbers greater than x: n - x

        // We need to assign:
        // - countLess distinct numbers from the (x - 1) numbers less than x
        // - countGreater distinct numbers from the (n - x) numbers greater than x
        // - The rest can be any of the remaining numbers

        // If countLess > (x - 1) or countGreater > (n - x), it's impossible
        if (countLess > x - 1 || countGreater > n - x) {
            System.out.println(0);
            return;
        }

        // Number of ways:
        // 1. Choose countLess numbers from (x - 1) and arrange them in the countLess positions: P(x-1, countLess) = (x-1)! / (x-1-countLess)!
        // 2. Choose countGreater numbers from (n - x) and arrange them in the countGreater positions: P(n-x, countGreater) = (n-x)! / (n-x-countGreater)!
        // 3. The remaining positions: total remaining positions = n - 1 - countLess - countGreater
        //    Remaining numbers: (x - 1 - countLess) + (n - x - countGreater) = n - 1 - countLess - countGreater
        //    Arrange these in the remaining positions: (n - 1 - countLess - countGreater)!

        // So the answer is:
        // P(x-1, countLess) * P(n-x, countGreater) * (n - 1 - countLess - countGreater)!

        long ans = fact[x - 1] * modInverse(fact[x - 1 - countLess]) % MOD;
        ans = ans * fact[n - x] % MOD;
        ans = ans * modInverse(fact[n - x - countGreater]) % MOD;
        ans = ans * fact[n - 1 - countLess - countGreater] % MOD;

        System.out.println(ans);
    }

    static long modInverse(long a) {
        return modPow(a, MOD - 2);
    }

    static long modPow(long base, long exp) {
        long result = 1;
        base %= MOD;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = result * base % MOD;
            }
            base = base * base % MOD;
            exp >>= 1;
        }
        return result;
    }
}
