        // Remaining positions = n - 1 - k.
        // Number of ways to arrange the remaining values in the remaining positions = (n - 1 - k)!.

        long remaining = n - 1 - k;
        long waysRemaining = fact[remaining];

        long result = waysLess * waysGreater % MOD;
        result = result * waysRemaining % MOD;

