        // Re-simulate to collect the midpoints before 'pos'
        l = 0;
        r = n - 1;
        while (l <= r) {
            int mid = (l + r) / 2;
            if (mid == pos) {
                break;
            } else if (mid < pos) {
                countLess++;
                l = mid + 1;
            } else {
                countGreater++;
                r = mid - 1;
            }
        }

        // The positions that must be < x: countLess positions
        // The positions that must be > x: countGreater positions
        // Position 'pos' must be x

        // Available numbers < x: x - 1 numbers (1, 2, ..., x-1)
        // Available numbers > x: n - x numbers (x+1, x+2, ..., n)

        // We need to assign:
        // - countLess distinct numbers from the (x-1) available numbers < x to the countLess positions
        // - countGreater distinct numbers from the (n-x) available numbers > x to the countGreater positions
        // - The remaining (n - 1 - countLess - countGreater) positions get the remaining numbers

        // Number of ways:
        // C(x-1, countLess) * (x-1)! / ((x-1-countLess)!) ... wait, let me think more carefully.

        // We have countLess specific positions that must contain values < x.
        // We have (x-1) available values < x.
        // Number of ways to choose and assign: P(x-1, countLess) = (x-1)! / (x-1-countLess)!

        // Similarly for > x: P(n-x, countGreater) = (n-x)! / (n-x-countGreater)!

        // The remaining positions: n - 1 - countLess - countGreater positions
        // Remaining values: (x-1 - countLess) + (n-x - countGreater) = n - 1 - countLess - countGreater
        // Number of ways to assign: (n - 1 - countLess - countGreater)!

        if (countLess > x - 1 || countGreater > n - x) {
            System.out.println(0);
            return;
        }

        long result = 1;

        // P(x-1, countLess) = (x-1)! / (x-1-countLess)!
        if (countLess > 0) {
            result = result * fact[x - 1] % MOD;
            result = result * modInverse(fact[x - 1 - countLess], MOD) % MOD;
        }

        // P(n-x, countGreater) = (n-x)! / (n-x-countGreater)!
        if (countGreater > 0) {
            result = result * fact[n - x] % MOD;
            result = result * modInverse(fact[n - x - countGreater], MOD) % MOD;
        }

        // Remaining positions
        int remaining = n - 1 - countLess - countGreater;
        if (remaining >= 0) {
            result = result * fact[remaining] % MOD;
        }

        System.out.println(result);
    }

    static long modInverse(long a, long mod) {
        return modPow(a, mod - 2, mod);
    }

    static long modPow(long base, long exp, long mod) {
        long result = 1;
        base %= mod;
        while (exp > 0) {
            if (exp % 2 == 1) {
                result = result * base % mod;
            }
            base = base * base % mod;
            exp /= 2;
        }
        return result;
    }
