import java.util.*;
import java.io.*;

public class Main {
    static final long MOD = 1000000007L;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int x = Integer.parseInt(st.nextToken());
        int pos = Integer.parseInt(st.nextToken());

        // Precompute factorials up to n
        long[] fact = new long[n + 1];
        fact[0] = 1;
        for (int i = 1; i <= n; i++) {
            fact[i] = fact[i - 1] * i % MOD;
        }

        // Simulate binary search to find which positions are visited
        // and determine the constraints on the array values at those positions
        // The binary search algorithm:
        // l = 0, r = n - 1
        // while l <= r:
        //   mid = (l + r) / 2
        //   if a[mid] == x: return true
        //   else if a[mid] < x: l = mid + 1
        //   else: r = mid - 1
        // return false

        // We need the algorithm to find x at position pos.
        // This means:
        // 1. The algorithm must visit position pos at some point.
        // 2. When it visits pos, a[pos] must be x.
        // 3. For all other positions visited before pos, the comparison must direct the search towards pos.
        // 4. The search must not terminate before reaching pos.

        // Let's trace the binary search and record the sequence of midpoints.
        // We also need to know for each visited position (except pos), whether the search goes left or right.

        // Actually, let's think about it differently.
        // The binary search visits a specific sequence of indices. Let's call this sequence S.
        // For the algorithm to find x at pos, pos must be in S.
        // Let the sequence of visited indices be m_1, m_2, ..., m_k where m_j is the j-th mid.
        // The algorithm stops when it finds x or when l > r.
        // We need the algorithm to stop exactly when it reaches pos (i.e., a[pos] == x is checked and returns true).

        // So, for all j such that m_j != pos and m_j comes before pos in the sequence:
        //   If the next step goes to the right (l = m_j + 1), then a[m_j] < x.
        //   If the next step goes to the left (r = m_j - 1), then a[m_j] > x.
        // And at the step where m_j == pos, we have a[pos] = x.

        // Let's simulate and record:
        // - The order of visited positions.
        // - For each position visited before pos, the direction of the next step.

        int l = 0, r = n - 1;
        List<Integer> visited = new ArrayList<>();
        List<Integer> directions = new ArrayList<>(); // 0 for left, 1 for right, -1 for not applicable (pos itself)

        boolean foundPos = false;
        while (l <= r) {
            int mid = (l + r) / 2;
            if (mid == pos) {
                foundPos = true;
                visited.add(mid);
                directions.add(-1);
                break;
            }
            visited.add(mid);
            // Determine direction: if mid < pos, we need to go right, so a[mid] < x
            // if mid > pos, we need to go left, so a[mid] > x
            if (mid < pos) {
                // We need to go right: l = mid + 1
                directions.add(1); // right
                l = mid + 1;
            } else {
                // We need to go left: r = mid - 1
                directions.add(0); // left
                r = mid - 1;
            }
        }

        if (!foundPos) {
            System.out.println(0);
            return;
        }

        // Now, let's count the constraints.
        // Let:
        //   lessCount = number of positions visited before pos where we need a[i] < x
        //   greaterCount = number of positions visited before pos where we need a[i] > x
        //   totalVisitedBeforePos = visited.size() - 1 (since the last one is pos)

        int lessCount = 0;
        int greaterCount = 0;
        for (int i = 0; i < visited.size() - 1; i++) {
            if (directions.get(i) == 1) {
                lessCount++;
            } else {
                greaterCount++;
            }
        }

        // The numbers available for the "less" positions are {1, 2, ..., x-1}, which has (x-1) elements.
        // The numbers available for the "greater" positions are {x+1, x+2, ..., n}, which has (n-x) elements.

        // We need to assign distinct numbers from {1, ..., x-1} to the lessCount positions.
        // Number of ways: P(x-1, lessCount) = (x-1)! / (x-1-lessCount)!
        // Similarly, assign distinct numbers from {x+1, ..., n} to the greaterCount positions.
        // Number of ways: P(n-x, greaterCount) = (n-x)! / (n-x-greaterCount)!

        // The remaining positions (n - 1 - lessCount - greaterCount) can be filled with any of the remaining numbers.
        // Total numbers not used: (x-1 - lessCount) + (n-x - greaterCount) = n - 1 - lessCount - greaterCount
        // Number of ways to arrange these: (n - 1 - lessCount - greaterCount)!

        // Total permutations = P(x-1, lessCount) * P(n-x, greaterCount) * (n - 1 - lessCount - greaterCount)!

        if (lessCount > x - 1 || greaterCount > n - x) {
            System.out.println(0);
            return;
        }

        long result = 1;

        // P(x-1, lessCount) = (x-1)! / (x-1-lessCount)!
        if (lessCount > 0) {
            // Compute (x-1)! / (x-1-lessCount)!
            long num = fact[x - 1];
            long den = fact[x - 1 - lessCount];
            // We need modular inverse of den
            result = result * num % MOD * modInverse(den, MOD) % MOD;
        }

        // P(n-x, greaterCount) = (n-x)! / (n-x-greaterCount)!
        if (greaterCount > 0) {
            long num = fact[n - x];
            long den = fact[n - x - greaterCount];
            result = result * num % MOD * modInverse(den, MOD) % MOD;
        }

        // Multiply by (n - 1 - lessCount - greaterCount)!
        int remaining = n - 1 - lessCount - greaterCount;
        result = result * fact[remaining] % MOD;

        System.out.println(result);
    }

    static long modInverse(long a, long mod) {
        return pow(a, mod - 2, mod);
    }

    static long pow(long base, long exp, long mod) {
        long result = 1;
        base = base % mod;
        while (exp > 0) {
            if (exp % 2 == 1) {
                result = result * base % mod;
            }
            exp = exp >> 1;
            base = base * base % mod;
        }
        return result;
    }
}
